def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def_count = 0
    for m, o in history:
        if o == 'D':
            opp_def_count += 1

    if opp_def_count == 0:
        if n < 5:
            return 'C'
        if n == 5:
            return 'D'
        if n == 6:
            return 'C'
        if n >= 7:
            return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        return 'C'

    if n >= 3:
        if history[-2][1] == 'C' and history[-3][1] == 'D':
            return 'C'

    if n >= 7 and history[5][0] == 'D' and history[5][1] == 'C':
        def_since = 0
        for i in range(6, n):
            if history[i][1] == 'D':
                def_since += 1
        if def_since <= 2:
            return 'C'

    opp_def_streak = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    if 4 <= opp_def_streak <= 5:
        return 'C'

    return 'D'
